draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 50; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 1.1) * 100, 2, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20 + Math.sin(t * 2) * 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('?', W / 2, H / 2);
  ctx.restore();
}
